'use strict';
// Kullanıcının mevcut prototipinde test ettiği 9 Kadıköy yönlü varyant korunmuştur.
const API_URL = 'https://iettapi.pcislocked.net/v1/stops/200051/arrivals';
const $ = id => document.getElementById(id);
const statusEl = $('status'), listEl = $('vehicles'), refreshButton = $('refresh'), moreEl = $('more');
let isLoading = false;

function xy(lat, lon, baseLat, baseLon) {
  return [(lon-baseLon)*111320*Math.cos(baseLat*Math.PI/180), (lat-baseLat)*111320];
}
function projection(bus, p, q) {
  const [ax,ay] = xy(p[1],p[2],bus.latitude,bus.longitude);
  const [bx,by] = xy(q[1],q[2],bus.latitude,bus.longitude);
  const dx=bx-ax, dy=by-ay, den=dx*dx+dy*dy;
  const t=den?Math.max(0,Math.min(1,-(ax*dx+ay*dy)/den)):0;
  return {distance:Math.hypot(ax+t*dx,ay+t*dy),t};
}
function remainingStops(bus){
  if(!Number.isFinite(bus.latitude)||!Number.isFinite(bus.longitude))return null;
  const matches=[];
  for(const route of ROUTES){
    const points=route.points;
    let best=null;
    for(let i=0;i<points.length-1;i++){
      const p=projection(bus,points[i],points[i+1]);
      if(best===null||p.distance<best.distance)best={...p,i};
    }
    if(best)matches.push({variant:route.id,distance:best.distance,remaining:points.length-best.i-1});
  }
  if(!matches.length)return null;
  matches.sort((a,b)=>a.distance-b.distance);
  const bestDist=matches[0].distance;
  if(bestDist>250)return null; // Güzergâha uzak aracı sahte kesinlikle eşleme.
  const candidates=matches.filter(x=>x.distance<=Math.min(250,bestDist+75));
  const counts=candidates.map(x=>x.remaining);
  return {min:Math.min(...counts),max:Math.max(...counts)};
}
function ageSeconds(hms){
  if(!hms||!/^\d{2}:\d{2}:\d{2}$/.test(hms))return null;
  const [h,m,s]=hms.split(':').map(Number);
  if(h>23||m>59||s>59)return null;
  const now=new Date();
  const nowSec=now.getHours()*3600+now.getMinutes()*60+now.getSeconds();
  const seen=h*3600+m*60+s;
  let delta=nowSec-seen;
  if(delta>43200)delta-=86400;
  if(delta< -43200)delta+=86400;
  return delta;
}
function createText(parent,tag,cls,value){
  const elem=document.createElement(tag);if(cls)elem.className=cls;
  elem.textContent=String(value);parent.appendChild(elem);return elem;
}
function makeCard(bus,index){
  const card=document.createElement('article');card.className='card'+(index===0?' primary':'');
  const header=createText(card,'div','card-top','');
  const info=createText(header,'div','','');
  createText(info,'div','plate','Araç '+(bus.kapino||'—'));
  createText(info,'div','plate',bus.plate||'Plaka bilinmiyor');
  const age=ageSeconds(bus.last_seen_ts);
  const stale=age!==null&&(age>240||age< -120);
  const minutes=Number(bus.eta_minutes);
  createText(header,'div','eta',!stale&&Number.isFinite(minutes)&&minutes>=0?Math.round(minutes)+' dk':'— dk');
  if(stale){
    createText(card,'div','rem','Veri eski');
    createText(card,'div','detail','GPS zamanı: '+bus.last_seen_ts+' · Güncel durak hesabı gösterilmiyor.');
    return card;
  }
  const rem=remainingStops({latitude:Number(bus.lat),longitude:Number(bus.lon)});
  if(!rem){
    createText(card,'div','rem','— durak');
    createText(card,'div','detail','GPS konumu güzergâhla güvenilir eşleşmedi.');
    return card;
  }
  const exact=rem.min===rem.max;
  createText(card,'div','rem'+(exact?'':' range'),exact?'≈ '+rem.min+' durak':rem.min+'–'+rem.max+' durak');
  createText(card,'div','detail',exact?'GPS tabanlı tahmin':'Güzergâh belirsiz · tahmini aralık');
  return card;
}
function live13(arrivals){
  return arrivals.filter(b =>
    String(b.route_code).trim()==='13' &&
    String(b.destination||'').toLocaleUpperCase('tr-TR').includes('KADIKÖY')
  ).sort((a,b)=>{
    const aEta=Number(a.eta_minutes),bEta=Number(b.eta_minutes);
    return (Number.isFinite(aEta)?aEta:Infinity)-(Number.isFinite(bEta)?bEta:Infinity);
  });
}
async function refresh(){
  if(isLoading)return;
  isLoading=true;refreshButton.disabled=true;refreshButton.textContent='…';
  statusEl.textContent='Canlı veriler sorgulanıyor…';
  try{
    const response=await fetch(API_URL,{cache:'no-store',headers:{Accept:'application/json'}});
    if(!response.ok)throw new Error('HTTP '+response.status);
    const data=await response.json();
    if(!Array.isArray(data))throw new Error('API beklenmeyen veri döndürdü');
    const buses=live13(data);
    listEl.replaceChildren();
    for(const [index,bus] of buses.slice(0,2).entries())listEl.appendChild(makeCard(bus,index));
    if(!buses.length)createText(listEl,'div','empty','Şu anda yaklaşan 13 aracı bildirilmiyor.');
    const hidden=Math.max(0,buses.length-2);
    moreEl.hidden=!hidden;
    if(hidden)moreEl.textContent='+'+hidden+' araç daha var · yalnızca ilk iki araç gösteriliyor';
    statusEl.textContent=new Date().toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit',second:'2-digit'})+' · '+buses.length+' yaklaşan araç';
  }catch(err){
    listEl.replaceChildren();moreEl.hidden=true;
    createText(listEl,'div','empty error','Canlı veri alınamadı. İnternet bağlantısı veya API erişimi kontrol edilmeli.');
    statusEl.textContent='Bağlantı hatası: '+(err instanceof Error?err.message:'Bilinmiyor');
  }finally{
    isLoading=false;refreshButton.disabled=false;refreshButton.textContent='Yenile';
  }
}
refreshButton.addEventListener('click',refresh);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh();});
setInterval(()=>{if(document.visibilityState==='visible')refresh();},30000);
if('serviceWorker' in navigator && (location.protocol==='https:' || location.hostname==='localhost')){
  window.addEventListener('load',()=>{navigator.serviceWorker.register('./sw.js').catch(()=>{});});
}
refresh();